// Static review catalog. Draft names and display entries never grant permissions or enroll pets.
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function buildPetCatalog(catalog, map) {
  const cards = catalog.programs.map(p=>{
    const n=map.nodes.find(n=>n.programNumber===p.number);
    const picture=n?.icon?`<img alt="" src="${esc(n.icon)}">`:'<span class="placeholder" aria-label="Artwork not made">?</span>';
    const icon=n?.programUrl?`<a href="${esc(n.programUrl)}" aria-label="Open ${esc(p.program)}" target="_blank" rel="noopener">${picture}</a>`:picture;
    const launch=n?.programUrl?`<p><a href="${esc(n.programUrl)}" target="_blank" rel="noopener">Open Pet Program</a></p>`:'<p class="note">Pet Program page not linked yet.</p>';
    const proposal=p.number===77?'The Triage Desk':p.idea;
    return `<article data-stage="${esc(p.stage)}"><div class="top">${icon}<div><small>#${p.number} · ${esc(p.stage)}</small><h2>${esc(p.icon)}</h2></div></div><p><b>${esc(p.program)}</b> · ${p.assigned?'Assigned name':'Needs a program name'}</p>${!p.assigned?`<p class="idea">Proposed: ${esc(proposal || 'Name still needed')}${p.number===77?' · Mascot idea: Vet Vole':''}</p>`:''}<p>${esc(p.mini_descriptor.text)}</p><p class="note">${esc(p.implementation_status||(p.stage==='seed'||p.stage==='roadmap'?'Planned; no working app is implied.':'Catalog status; runtime health has not been verified here.'))}</p>${launch}${n?`<a href="system-map-20261012.html#node=${encodeURIComponent(n.id)}">Locate on map</a>`:''}${p.repo_exists?` · <a href="https://github.com/findastra/${encodeURIComponent(p.repo)}">Repository</a>`:''}</article>`;
  }).join('\n');
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Astra's PetOS · All pets and names</title><style>body{margin:0;background:#101727;color:#edf2ff;font:17px/1.5 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:28px}a{color:#9ddfff}h1{font-size:clamp(28px,4vw,44px)}h2{font-size:20px;margin:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,290px),1fr));gap:16px}article{border:1px solid #455571;border-radius:16px;padding:20px;background:#1b263b}.top{display:flex;align-items:center;gap:12px}img,.placeholder{width:60px;height:60px;object-fit:contain;flex-shrink:0}.placeholder{display:grid;place-items:center;background:#34425d;border-radius:50%;font-size:28px}.idea{color:#f1d899}.note,small{color:#b8c6dc}input{font:inherit;padding:12px;width:min(100%,480px);box-sizing:border-box;border-radius:8px;margin:12px 0 24px}article[hidden]{display:none}</style><main><a href="system-map-20261012.html">← System map</a><h1>All pets and proposed names</h1><p>${catalog.programs.length} pet programs · ${catalog.programs.filter(p=>p.assigned).length} assigned program names · ${catalog.programs.filter(p=>!p.assigned).length} awaiting names. Proposals below are for your review, not automatic renames.</p><p>Includes Intel Owl from the October 14 phone handoff. Existing art is shown where available; question marks mean artwork has not been made. Showing a pet here does not install it, start a worker, or grant access.</p><label for="search">Find a pet, job or name</label><br><input id="search" type="search" placeholder="Search all pets…"><section class="grid">${cards}</section></main><script>document.getElementById('search').addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('article').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(q));});</script></html>`;
}
